-- Wächter Migration 209 (nur lesen). Erwartungen: werkzeuge/m209_md5.json. funktionen = die von 209 geänderten und neuen Funktionen.
SELECT (SELECT md5(string_agg(p.proname::text || '(' || pg_get_function_identity_arguments(p.oid) || ')|' || pg_get_function_result(p.oid) || '|' || md5(p.prosrc), E'\n' ORDER BY p.proname::text || '(' || pg_get_function_identity_arguments(p.oid) || ')' COLLATE "C")) FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace WHERE n.nspname::text = 'public' COLLATE "C" AND p.proname::text COLLATE "C" = ANY (ARRAY['ally_systemnachricht_inhalt', 'talent_zugang_ui', 'talents_warnungen', 'talent_einladung_rueckweg', 'ally_ui_verbindung_link', 'ally_ui_pfad_teil', 'ally_ui_pfad_lesen', 'ally_ui_pfad', 'ally_ui_ort', 'ally_ui_abfrage', 'ally_ui_pfade_an', 'ally_ui_link', 'ally_ui_pfade_liste', 'ally_ui_filter'])) AS funktionen;
